 pub fn advance(&mut self,bytes:&[u8],grant:usize)->Result<FontProgress,String>{if grant==0{return Err("Invalid glyph work grant".into());}if self.cancelled{return Err("Font outline cancelled".into());}if let Some(error)=&self.owners.failure{return Err(error.clone());}for _ in 0..grant{if self.phase==4{break;}if self.work==self.limits.max_work{self.owners.failure=Some("Font outline work limit exceeded".into());return Err(self.owners.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(bytes){self.owners.failure=Some(error.clone());return Err(error);}self.work+=1;}Ok(FontProgress{phase:match self.phase{0=>"source",1=>"contourSource",2=>"contourStart",3=>"contour",_=>"complete"},work:self.work,done:self.phase==4})}
